const ids = ["3:149","3:155","3:158","3:161","3:164","3:143","3:146","3:140","3:122"];
const out = [];
function walk(n, depth) {
  let s = "  ".repeat(depth) + n.name + " [" + n.type + "]";
  if ("fills" in n && Array.isArray(n.fills) && n.fills.length) {
    s += " fills=" + n.fills.map(f=>f.type==="SOLID"?("#"+Object.values(f.color).map(c=>Math.round(c*255).toString(16).padStart(2,"0")).join("")):f.type).join(",");
  }
  if ("strokes" in n && Array.isArray(n.strokes) && n.strokes.length) {
    s += " strokes=" + n.strokes.map(f=>f.type==="SOLID"?("#"+Object.values(f.color).map(c=>Math.round(c*255).toString(16).padStart(2,"0")).join("")):f.type).join(",");
  }
  out.push(s);
  if ("children" in n && depth < 4) n.children.forEach(c=>walk(c, depth+1));
}
for (const id of ids) {
  const n = await figma.getNodeByIdAsync(id);
  out.push("=== " + id);
  walk(n, 0);
}
// workspace page
