const solid = c => [{type:"SOLID",color:c}];
function txt(chars, style, size, color, opts={}) {
  const t = figma.createText();
  t.fontName = {family:"Inter",style};
  t.fontSize = size;
  t.characters = chars;
  t.fills = solid(color);
  if (opts.name) t.name = opts.name;
  if (opts.lh) t.lineHeight = {value:opts.lh,unit:"PIXELS"};
  if (opts.center) { t.textAlignHorizontal="CENTER"; }
  if (opts.w) { t.resize(opts.w, t.height); t.textAutoResize="HEIGHT"; }
  return t;
}
function frame(name, w, h, fill, layout) {
  const f = figma.createFrame();
  f.name = name; f.resize(w,h);
  f.fills = fill? solid(fill) : [];
  if (layout) { f.layoutMode=layout; f.primaryAxisSizingMode="AUTO"; f.counterAxisSizingMode="AUTO"; }
  return f;
}
function rect(w,h,fill,radius,name){const r=figma.createRectangle();r.resize(w,h);r.fills=solid(fill);if(radius!==undefined)r.cornerRadius=radius;if(name)r.name=name;return r;}
function vec(pathData, w, h, strokeColor, strokeW, name){
  const v = figma.createVector();
  v.vectorPaths = [{pathData, windingRule:"NONZERO"}];
  v.resize(w,h);
  v.fills=[];
  v.strokes = solid(strokeColor);
  v.strokeWeight = strokeW;
  v.strokeCap="ROUND"; v.strokeJoin="ROUND";
  if(name)v.name=name;
  return v;
}

