const dump = (x, d) => {
  let s = " ".repeat(d*2) + x.type + " " + x.name;
  if (x.type === "VECTOR" || x.type === "RECTANGLE" || x.type === "ELLIPSE" || x.type==="FRAME" || x.type==="COMPONENT" || x.type==="GROUP" || x.type==="INSTANCE") {
    try { s += " fills=" + JSON.stringify(x.fills).slice(0,120); } catch(e){}
  }
  let out = [s];
  if ("children" in x) x.children.forEach(c => out = out.concat(dump(c, d+1)));
  return out;
};
