    const col=active?C.primary:C.faint;
    const lbl=find(tab,"Label"); if(lbl){lbl.characters=lbl.characters; lbl.fills=solid(col); if(active)lbl.fontName={family:"Inter",style:"Semi Bold"};}
    const icon=tab.children.find(c=>c.type==="INSTANCE"); if(icon)paintVectors(icon,col);
  }
}
