const C = {
  primary:{r:0x3E/255,g:0x52/255,b:0xC1/255},
  ink:{r:0x1A/255,g:0x20/255,b:0x2C/255},
  sub:{r:0x71/255,g:0x80/255,b:0x96/255},
  faint:{r:0x98/255,g:0xA2/255,b:0xB3/255},
  line:{r:0xE4/255,g:0xE7/255,b:0xEC/255},
  white:{r:1,g:1,b:1},
  gain:{r:0x0F/255,g:0xA6/255,b:0x5C/255},
  loss:{r:0xE5/255,g:0x48/255,b:0x4D/255},
  soft:{r:0xF5/255,g:0xF6/255,b:0xFA/255},
  gainSoft:{r:0xE7/255,g:0xF7/255,b:0xEF/255},
  lossSoft:{r:0xFD/255,g:0xEC/255,b:0xEC/255},
};
const solid=c=>[{type:"SOLID",color:c}];
function txt(chars,style,size,color,name){const t=figma.createText();t.fontName={family:"Inter",style};t.fontSize=size;t.characters=chars;t.fills=solid(color);if(name)t.name=name;return t;}
function rect(w,h,fill,radius,name){const r=figma.createRectangle();r.resize(w,h);r.fills=solid(fill);if(radius!==undefined)r.cornerRadius=radius;if(name)r.name=name;return r;}
async function ins(id){const comp=await figma.getNodeByIdAsync(id);return comp.createInstance();}
function find(node,name){if(node.name===name)return node;if("children" in node){for(const ch of node.children){const r=find(ch,name);if(r)return r;}}return null;}
function paintVectors(node,color){if(node.type==="VECTOR"||node.type==="ELLIPSE"||node.type==="RECTANGLE"||node.type==="LINE"){try{if(node.fills&&node.fills.length)node.fills=solid(color);}catch(e){}}if("children" in node)node.children.forEach(c=>paintVectors(c,color));}
function sparkPath(vals,w,h){
  const mn=Math.min(...vals),mx=Math.max(...vals),rg=(mx-mn)||1;
  return vals.map((v,i)=>{
    const x=(i/(vals.length-1))*w, y=h-2-((v-mn)/rg)*(h-4);
    return (i===0?"M":"L")+x.toFixed(1)+" "+y.toFixed(1);
  }).join(" ");
}
async function setTabActive(inst,tabName){
  for(const tn of ["Tab_Home","Tab_Portfolio","Tab_Market","Tab_Profile"]){
    const tab=find(inst,tn); if(!tab)continue;
    const active=(tn===tabName);
    const col=active?C.primary:C.faint;
    const lbl=find(tab,"Label"); if(lbl){lbl.fills=solid(col); if(active)lbl.fontName={family:"Inter",style:"Semi Bold"};}
    const icon=tab.children.find(c=>c.type==="INSTANCE"); if(icon)paintVectors(icon,col);
  }
}
function setBtnLabel(inst,label){
  const t=inst.children.find(c=>c.type==="TEXT");
  t.characters=label;
}
