  lg.x=inst.x+slot.x+(40-lg.width)/2; lg.y=inst.y+slot.y+(40-lg.height)/2;
  frame.appendChild(lg);
  find(inst,"Ticker").characters=ticker;
  find(inst,"Company").characters=company;
  find(inst,"Price").characters=price;
  const pill=find(inst,"ChangePill"); pill.fills=solid(up?C.gainSoft:C.lossSoft); pill.cornerRadius=6;
  const ch=find(inst,"Change"); ch.characters=change; ch.fills=solid(up?C.gain:C.loss);
  const sp=find(inst,"Spark"); if(sp)sp.visible=false;
  const v=figma.createVector();
  v.vectorPaths=[{data:sparkPath(spark,48,18),windingRule:"NONZERO"}];
  v.resize(48,18); v.x=inst.x+279; v.y=inst.y+(inst.height-18)/2;
  v.fills=[]; v.strokes=solid(up?C.gain:C.loss); v.strokeWeight=1.5; v.name="Spark";
  frame.appendChild(v);
}

