function paintVectors(node,color){if(node.type==="VECTOR"||node.type==="ELLIPSE"||node.type==="RECTANGLE"||node.type==="LINE"){try{if(node.fills&&node.fills.length)node.fills=solid(color);}catch(e){}}if("children" in node)node.children.forEach(c=>paintVectors(c,color));}
async function setTabActive(inst,tabName){
