const ids=["39:34","39:64","39:88","39:136","40:118","40:172","40:229","44:216","46:357","46:466","47:454","47:509"];
const out=[];
for(const id of ids){
  const n=await figma.getNodeByIdAsync(id);
  out.push(id+" "+n.type+" "+n.name+" parent="+n.parent.type+" "+n.parent.name+" ("+n.parent.id+")");
}
return out.join("\n");

function find(node,name){if(node.name===name)return node;if("children" in node){for(const ch of node.children){const r=find(ch,name);if(r)return r;}}return null;}
function inInstance(n, stop){ let p=n.parent; while(p && p.id!==stop.id){ if(p.type==="INSTANCE") return p.name; p=p.parent;} return null; }
const checks=[["40:118","Back"],["40:118","Send code"],["40:172","Back"],["40:172","Verify account"],["44:216","PortfolioCard"],["44:216","TabBar"],["46:357","Back"],["46:466","Back"],["46:466","BuyStocks"],["47:454","Back"],["47:454","ConfirmOrder"],["39:64","Sign up"],["39:64","Skip"],["39:136","Continue"],["40:229","I’m ready to start!"]];
const out=[];
for(const [fid,name] of checks){
  const f=await figma.getNodeByIdAsync(fid);
  const n=find(f,name);
  if(!n){out.push(f.name+" / "+name+" => NOT FOUND");continue;}
  const inst=inInstance(n,f);
  out.push(f.name+" / "+name+" => "+n.type+" "+n.id+" insideInstance="+(inst||"no")+" @"+Math.round(n.absoluteTransform[0][2]-f.absoluteTransform[0][2])+","+Math.round(n.absoluteTransform[1][2]-f.absoluteTransform[1][2])+" "+Math.round(n.width)+"x"+Math.round(n.height));
}
// also stock rows
for(const fid of ["44:216","46:357"]){
  const f=await figma.getNodeByIdAsync(fid);
  const rows=[]; const walk=n=>{if(n.name==="StockRow")rows.push(n);if("children" in n)n.children.forEach(walk);}; walk(f);
  rows.forEach((r,i)=>out.push(f.name+" StockRow["+i+"] "+r.type+" "+r.id+" @"+Math.round(r.x)+","+Math.round(r.y)));
}
return out.join("\n");

const F = {
