// clear existing reactions recursively
function clear(n){ try{ if("reactions" in n && n.reactions.length) n.reactions=[]; }catch(e){} if("children" in n) n.children.forEach(clear); }
for(const k in nodes) clear(nodes[k]);
// remove old hotspots if any
for(const k in nodes){ for(const c of [...nodes[k].children]){ if(c.name.startsWith("Hotspot_")) c.remove(); } }

function nav(dest){
  return {actions:[{type:"NODE",destinationId:dest.id,navigation:"NAVIGATE",
    transition:{type:"SMART_ANIMATE",duration:0.3,easing:{type:"EASE_IN_AND_OUT"}},
    resetVideoPosition:false,resetScrollPosition:false,preserveScrollPosition:false}],
    trigger:{type:"ON_CLICK"}};
}
function link(src, dest){ if(src && dest && src.id!==dest.id) src.reactions=[...src.reactions, nav(dest)]; }
function find(node,name){if(node.name===name)return node;if("children" in node){for(const ch of node.children){const r=find(ch,name);if(r)return r;}}return null;}
function findAll(node,name,out){out=out||[];if(node.name===name)out.push(node);if("children" in node)node.children.forEach(c=>findAll(c,name,out));return out;}
function hotspot(frame,name,x,y,w,h,dest){
  const r=figma.createRectangle();
  r.name=name; r.resize(w,h); r.x=x; r.y=y;
  r.fills=[]; r.strokes=[];
  frame.appendChild(r);
  link(r,dest);
  return r;
}

